package com.nook.phone;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.graphics.PixelFormat;import android.graphics.drawable.GradientDrawable;import android.provider.Settings;import android.view.*;import android.widget.*;import org.json.*;import java.util.concurrent.*;

/** User-started, revocable activity overlay. It never grants an approval itself. */
public final class IslandService extends Service {
    private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService network=Executors.newSingleThreadExecutor();private WindowManager manager;private LinearLayout island;private TextView label;private NookApi api;private volatile boolean checking,closed;private String last="";
    private final Runnable poll=new Runnable(){public void run(){if(closed)return;if(!checking){checking=true;network.execute(()->{try{JSONObject state=api.request("/state","GET",null);handler.post(()->paint(state));}catch(Exception ignored){handler.post(()->{if(!closed){label.setText("Nook · reconnecting");island.setVisibility(View.VISIBLE);}});}finally{checking=false;}});}PowerManager power=(PowerManager)getSystemService(POWER_SERVICE);handler.postDelayed(this,power.isInteractive()?5000:30000);}};
    @Override public void onCreate(){super.onCreate();api=new NookApi(this);NotificationManager notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);notifications.createNotificationChannel(new NotificationChannel("nook-status","Nook activity",NotificationManager.IMPORTANCE_LOW));notifications.createNotificationChannel(new NotificationChannel("nook-requests","Nook requests",NotificationManager.IMPORTANCE_DEFAULT));Intent stop=new Intent(this,IslandService.class).setAction("stop");PendingIntent stopIntent=PendingIntent.getService(this,2,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification note=new Notification.Builder(this,"nook-status").setSmallIcon(R.drawable.nook_icon).setContentTitle("Nook activity island").setContentText("Connected to your local PC").setContentIntent(open()).addAction(new Notification.Action.Builder(null,"Stop",stopIntent).build()).setOngoing(true).build();if(Build.VERSION.SDK_INT>=34)startForeground(7,note,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(7,note);
      if(!api.paired()||!Settings.canDrawOverlays(this)){stopSelf();return;}manager=(WindowManager)getSystemService(WINDOW_SERVICE);island=new LinearLayout(this);island.setOrientation(LinearLayout.HORIZONTAL);island.setGravity(Gravity.CENTER_VERTICAL);island.setPadding(20,10,26,10);GradientDrawable background=new GradientDrawable();background.setColor(Color.BLACK);background.setCornerRadius(42);island.setBackground(background);PetView pet=new PetView(this);island.addView(pet,new LinearLayout.LayoutParams(52,52));label=new TextView(this);label.setTextColor(Color.WHITE);label.setTextSize(13);label.setMaxLines(2);island.addView(label);island.setOnClickListener(v->{try{open().send();}catch(PendingIntent.CanceledException ignored){}});WindowManager.LayoutParams params=new WindowManager.LayoutParams(320,WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_SECURE,PixelFormat.TRANSLUCENT);params.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;params.y=18;manager.addView(island,params);handler.post(poll);}
    private PendingIntent open(){return PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
    private void paint(JSONObject state){if(closed||island==null)return;JSONObject pending=state.optJSONObject("pending");JSONArray sessions=state.optJSONArray("sessions");int active=0;if(sessions!=null)for(int i=0;i<sessions.length();i++)if(!sessions.optJSONObject(i).optBoolean("finished"))active++;String copy=pending!=null?"Nook · review needed":active>0?active+" agent"+(active==1?" is":"s are")+" working":"Nook · all quiet";label.setText(copy);island.setVisibility(pending!=null||active>0?View.VISIBLE:View.GONE);NookWidget.updateState(this,state);if(pending!=null&&!pending.optString("id").equals(last)){last=pending.optString("id");Notification note=new Notification.Builder(this,"nook-requests").setSmallIcon(R.drawable.nook_icon).setContentTitle("Nook needs your attention").setContentText("Review the request on your phone").setContentIntent(open()).addAction(new Notification.Action.Builder(null,"Review",open()).build()).setAutoCancel(true).build();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(8,note);}if(pending==null)last="";}
    @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"stop".equals(intent.getAction()))stopSelf();return START_NOT_STICKY;}
    @Override public IBinder onBind(Intent intent){return null;}
    @Override public void onDestroy(){closed=true;handler.removeCallbacksAndMessages(null);network.shutdownNow();if(manager!=null&&island!=null)manager.removeView(island);super.onDestroy();}
}
